  function toast(message){if(typeof window.toast==='function'){window.toast(message);return}var x=document.createElement('div');x.textContent=message;x.style.cssText='position:fixed;left:50%;bottom:70px;transform:translateX(-50%);background:#17263d;color:#fff;padding:9px 14px;border-radius:7px;z-index:100001;font-size:12px';document.body.appendChild(x);setTimeout(function(){x.remove()},2200)}
