  function rules(host){var m=modal(host,'<div class="c3-dialog-head"><b>第三版规则说明</b><button data-close>×</button></div><div class="c3-dialog-body"><ul class="c3-rule-list"><li>关爱记录位于控辍保学页面，与预警记录、劝返记录并列。</li><li>每条记录独立保存，不形成可追加的关爱个案。</li><li>只展示本学年关爱记录，每次向下加载20条。</li><li>查看范围受学生数据权限控制；本人创建且有操作权限的记录才可编辑、删除。</li><li>创建时间由服务端写入且永不因编辑改变，列表按创建时间倒序。</li><li>提交时重新校验学生在读状态、年级班级和数据范围。</li><li>每次编辑、删除均由后端保存操作人、操作时间及前后快照。</li></ul></div><div class="c3-dialog-foot"><button class="c3-primary" data-close>知道了</button></div>');m.querySelectorAll('[data-close]').forEach(function(b){b.onclick=function(){m.remove()}})}
