  function freshDraft(){return {grade:'',className:'',studentId:'',sources:[],types:[],reason:'',careDate:today(),people:[],method:'',result:'',proofs:[],statusChecked:false,enrollmentChecked:false}}
  function openTeacherForm(id){var r=id?records.find(function(x){return x.id===id}):null;if(id&&!canEdit(r)){toast('暂无权限编辑该记录');return}teacherState.editing=r?{id:r.id,version:r.version}:null;teacherState.draft=r?Object.assign(clone(r),{grade:r.student.grade,className:r.student.className,statusChecked:true,enrollmentChecked:true}):freshDraft();renderTeacherForm();showTeacherScreen('sc-care3-form')}
  function options(values,selected,placeholder){return '<option value="">'+placeholder+'</option>'+values.map(function(v){return '<option value="'+esc(v)+'" '+(v===selected?'selected':'')+'>'+esc(v)+'</option>'}).join('')}
  function multi(values,selected){return values.map(function(v){return '<option value="'+esc(v)+'" '+(selected.indexOf(v)>=0?'selected':'')+'>'+esc(v)+'</option>'}).join('')}
  function renderTeacherForm(){var d=teacherState.draft,scope=students.filter(function(s){return inPath(s.org,ROOT)&&(account.view==='all'||s.teacher===account.name)}),grades=Array.from(new Set(scope.map(function(s){return s.grade}))),classes=Array.from(new Set(scope.filter(function(s){return s.grade===d.grade}).map(function(s){return s.className}))),pupils=scope.filter(function(s){return s.grade===d.grade&&s.className===d.className});var body=document.querySelector('#sc-care3-form [data-care3-body]');document.querySelector('#sc-care3-form .sub-hd b').textContent=teacherState.editing?'编辑关爱记录':'新增关爱记录';body.innerHTML='<form class="c3-form-scroll" id="care3-form"><div class="c3-section-title">学生信息</div><section class="c3-card">'+fieldSelect('年级','grade',options(grades,d.grade,'请选择年级'))+fieldSelect('班级','className',options(classes,d.className,'请选择班级'))+fieldSelect('学生姓名','studentId',options(pupils.map(function(s){return s.id}),d.studentId,'请选择学生').replace(/>(s-[^<]+)</g,function(all,id){var s=students.find(function(x){return x.id===id});return '>'+esc(s?s.name:id)+'<'}))+'</section><div class="c3-section-title">关爱内容</div><section class="c3-card">'+fieldMulti('关爱来源','sources',multi(SOURCES,d.sources))+fieldMulti('关爱类型','types',multi(TYPES,d.types))+fieldText('关爱原因','reason','请填写学生的真实情况',d.reason,true)+fieldDate(d.careDate)+fieldMulti('执行人员','people',multi(TEACHERS,d.people))+fieldSelect('关爱方式','method',options(METHODS,d.method,'请选择关爱方式'))+fieldText('关爱结果','result','请填写关爱过程和结果',d.result,false)+'<div class="c3-field"><label>证明材料</label><input type="file" accept="image/jpeg,image/png" multiple><div class="c3-muted">支持JPEG、JPG、PNG格式图片，最多九张，每张不超过10M</div><div class="c3-error" data-error="proofs"></div></div></section><div class="c3-error" data-error="save"></div></form><div class="c3-form-foot"><button class="c3-primary" data-save>确定</button></div>';
    var form=body.querySelector('#care3-form');form.querySelector('[name=grade]').onchange=function(){d.grade=this.value;d.className='';d.studentId='';renderTeacherForm()};form.querySelector('[name=className]').onchange=function(){d.className=this.value;d.studentId='';renderTeacherForm()};form.querySelector('[name=studentId]').onchange=function(){d.studentId=this.value;var s=students.find(function(x){return x.id===d.studentId});d.people=s?[s.teacher]:[];d.statusChecked=false;d.enrollmentChecked=false;renderTeacherForm()};form.querySelectorAll('select[multiple]').forEach(function(s){s.onchange=function(){d[s.name]=Array.from(s.selectedOptions).map(function(o){return o.value})}});form.querySelector('[name=method]').onchange=function(){d.method=this.value};form.querySelectorAll('textarea').forEach(function(t){t.oninput=function(){d[t.name]=t.value;var c=form.querySelector('[data-count='+t.name+']');if(c)c.textContent=t.value.length+'/100'}});form.querySelector('[data-date-open]').onclick=function(){calendarPicker(document.querySelector('.phone'),d.careDate,function(v){d.careDate=v;renderTeacherForm()})};form.querySelector('input[type=file]').onchange=function(){var files=Array.from(this.files);var err=form.querySelector('[data-error=proofs]');if(files.length>9){err.textContent='最多上传9张图片';return}if(files.some(function(f){return f.size>10*1024*1024})){err.textContent='每张图片不能超过10M';return}if(files.some(function(f){return !['image/jpeg','image/png'].includes(f.type)})){err.textContent='仅支持JPEG、JPG、PNG格式图片';return}d.proofs=files.map(function(f){return {name:f.name,size:f.size,type:f.type}});err.textContent=''};body.querySelector('[data-save]').onclick=saveTeacher}
  function fieldSelect(label,name,html){return '<div class="c3-field"><label>'+label+'<span class="c3-req">*</span></label><select name="'+name+'">'+html+'</select><div class="c3-error" data-error="'+name+'"></div></div>'}
  function fieldMulti(label,name,html){return '<div class="c3-field"><label>'+label+'<span class="c3-req">*</span></label><select multiple name="'+name+'">'+html+'</select><div class="c3-error" data-error="'+name+'"></div></div>'}
  function fieldText(label,name,placeholder,value,count){return '<div class="c3-field"><div class="c3-field-head"><label>'+label+'<span class="c3-req">*</span></label>'+(count?'<span class="c3-counter" data-count="'+name+'">'+value.length+'/100</span>':'')+'</div><textarea name="'+name+'" maxlength="100" placeholder="'+placeholder+'">'+esc(value)+'</textarea><div class="c3-error" data-error="'+name+'"></div></div>'}
  function fieldDate(value){return '<div class="c3-field"><label>关爱时间<span class="c3-req">*</span></label><button type="button" class="c3-plain" style="width:100%;text-align:left" data-date-open>'+esc(value||'请选择日期')+'</button><div class="c3-error" data-error="careDate"></div></div>'}
  function showFieldError(key,msg){var form=document.getElementById('care3-form'),e=form.querySelector('[data-error='+key+']')||form.querySelector('[data-error=save]');e.textContent=msg;e.closest('.c3-field')?.scrollIntoView({block:'center'})}
  function saveTeacher(){var d=teacherState.draft,form=document.getElementById('care3-form');form.querySelectorAll('.c3-error').forEach(function(e){e.textContent='' });if(!account.write){showFieldError('save','当前账号已无新增关爱记录权限，请联系管理员。');return}var st=students.find(function(s){return s.id===d.studentId});if(!d.grade)return showFieldError('grade','请选择年级');if(!d.className)return showFieldError('className','请选择班级');if(!st)return showFieldError('studentId','请选择学生姓名');if(st.simulateStatusChange&&!d.statusChecked){d.statusChecked=true;showFieldError('studentId','该学生当前不是在读状态，不能新增关爱记录，请重新选择学生。');return}if(st.simulateEnrollmentChange&&!d.enrollmentChecked){d.enrollmentChecked=true;st.grade=st.serverGrade;st.className=st.serverClass;d.grade=st.grade;d.className=st.className;renderTeacherForm();showFieldError('studentId','该学生的年级或班级已发生变化，已更新为“'+st.grade+'·'+st.className+'”，请确认后重新提交。');return}if(!inPath(st.org,ROOT)||(account.view!=='all'&&st.teacher!==account.name))return showFieldError('studentId','该学生已不在您的数据范围内，请重新选择学生。');if(!d.sources.length)return showFieldError('sources','请选择关爱来源');if(!d.types.length)return showFieldError('types','请选择关爱类型');if(!d.reason.trim())return showFieldError('reason','请填写关爱原因');if(d.reason.length>100)return showFieldError('reason','关爱原因最多100字');if(!validDate(d.careDate))return showFieldError('careDate','请选择有效关爱时间');if(!d.people.length)return showFieldError('people','请选择执行人员');if(!d.method)return showFieldError('method','请选择关爱方式');if(!d.result.trim())return showFieldError('result','请填写关爱结果');if(d.result.length>100)return showFieldError('result','关爱结果最多100字');var current=teacherState.editing&&records.find(function(r){return r.id===teacherState.editing.id});if(current&&!canEdit(current))return showFieldError('save','暂无权限编辑该记录');if(current&&current.version!==teacherState.editing.version)return showFieldError('save','记录已被其他人员修改，请刷新后重试');var value={studentId:st.id,student:{id:st.id,name:st.name,grade:st.grade,className:st.className,org:st.org.slice()},sources:d.sources.slice(),types:d.types.slice(),reason:d.reason.trim(),careDate:d.careDate,people:d.people.slice(),method:d.method,result:d.result.trim(),proofs:clone(d.proofs||[])};var saved;if(current){saved=Object.assign({},current,value,{updatedAt:now(),updatedBy:account.name,version:current.version+1});audit.push({action:'编辑',operator:account.name,operatedAt:saved.updatedAt,before:clone(current),after:clone(saved)});records.splice(records.indexOf(current),1,saved)}else{saved=Object.assign(value,{id:'r-'+String(++seq).padStart(5,'0'),createdBy:account.id,createdName:account.name,createdAt:now(),updatedAt:null,updatedBy:null,version:1});records.push(saved)}teacherState.draft=null;teacherState.editing=null;openTeacherDetail(saved.id);toast('保存成功')}
  function calendarPicker(host,value,done){var selected=validDate(value)?value:today(),y=Number(selected.slice(0,4)),mth=Number(selected.slice(5,7)),m=modal(host,'<b>选择关爱时间</b><div data-calendar style="margin-top:14px"></div><div class="c3-sheet-foot"><button class="c3-plain" data-close>取消</button><button class="c3-primary" data-ok>确定</button></div>',true);function render(){var first=new Date(Date.UTC(y,mth-1,1)).getUTCDay(),days=new Date(Date.UTC(y,mth,0)).getUTCDate(),cells=[];for(var i=0;i<first;i++)cells.push('<span></span>');for(var d=1;d<=days;d++){var date=y+'-'+String(mth).padStart(2,'0')+'-'+String(d).padStart(2,'0');cells.push('<button type="button" class="c3-day '+(date===selected?'on':'')+'" data-date="'+date+'">'+d+'</button>')}m.querySelector('[data-calendar]').innerHTML='<div class="c3-calendar-head"><button data-month="-1">‹</button><b>'+y+'年'+String(mth).padStart(2,'0')+'月</b><button data-month="1">›</button></div><div class="c3-week"><span>日</span><span>一</span><span>二</span><span>三</span><span>四</span><span>五</span><span>六</span></div><div class="c3-calendar-grid">'+cells.join('')+'</div>';m.querySelectorAll('[data-month]').forEach(function(b){b.onclick=function(){mth+=Number(b.dataset.month);if(mth===0){mth=12;y--}if(mth===13){mth=1;y++}render()}});m.querySelectorAll('[data-date]').forEach(function(b){b.onclick=function(){selected=b.dataset.date;render()}})}render();m.querySelector('[data-close]').onclick=function(){m.remove()};m.querySelector('[data-ok]').onclick=function(){done(selected);m.remove()}}
  var webState={org:ROOT.slice(),page:1,filter:{year:'',grade:'',className:'',name:'',source:'',start:today(),end:today()}};
  function installWeb(){var menu=document.querySelector('#menu-care-v1');if(menu){var span=menu.querySelector('span:last-child')||menu;span.textContent='关爱管理'}var name=isSchool?'schoolCareOpen':'cityCareOpen';window[name]=openWebCare;if(window.CARE_V3_FORCE_OPEN||location.hash==='#care-v3'||location.hash==='#school-care'||location.hash==='#city-care')setTimeout(openWebCare,0)}
  function openWebCare(){document.querySelectorAll('[id^="section-"]').forEach(function(s){s.classList.add('hidden')});var old=document.getElementById('section-care-menu-v1');if(!old){old=document.createElement('section');old.id='section-care-menu-v1';document.body.appendChild(old)}old.classList.remove('hidden');old.innerHTML='<div class="care3 care3-web" id="care3-web-root"></div>';var root=document.getElementById('care3-web-root'),side=document.querySelector('aside');if(root&&side)root.style.left=Math.max(0,side.getBoundingClientRect().right)+'px';webState.org=ROOT.slice();webState.page=1;renderWeb()}
  function children(path){if(path.length===0)return Object.keys(TREE);if(path.length===1)return Object.keys(TREE[path[0]]||{});if(path.length===2)return Object.keys((TREE[path[0]]||{})[path[1]]||{});if(path.length===3)return (((TREE[path[0]]||{})[path[1]]||{})[path[2]]||[]);return []}
  function pathName(path){return path.length?path[path.length-1]:'全国'}
  function webVisible(r,path){return inPath(r.student.org,path)}
  function webRecords(){var f=webState.filter;return sorted(records.filter(function(r){return webVisible(r,webState.org)&&(!f.year||yearOf(r.careDate)===f.year)&&(!f.grade||r.student.grade===f.grade)&&(!f.className||r.student.className===f.className)&&(!f.name||r.student.name.indexOf(f.name)>=0)&&(!f.source||r.sources.indexOf(f.source)>=0)&&(!f.start||r.createdAt.slice(0,10)>=f.start)&&(!f.end||r.createdAt.slice(0,10)<=f.end)}))}
  function renderWeb(){var root=document.getElementById('care3-web-root');if(!root)return;var atSchool=webState.org.length===4;if(isSchool)atSchool=true;root.innerHTML='<div class="c3-web-head"><div><h1>关爱管理'+(pathName(webState.org)?' — '+esc(pathName(webState.org)):'')+'</h1><div class="c3-muted">第三版 · 一条记录对应一次关爱</div></div><div><button class="c3-plain" data-rules>规则说明</button></div></div><div class="c3-breadcrumb">'+webState.org.map(function(n,i){return '<button class="c3-link" data-crumb="'+i+'">'+esc(n)+'</button><span>›</span>'}).join('')+'</div><div class="c3-panel">'+(atSchool?webList():webSummary())+'</div>';root.querySelector('[data-rules]').onclick=function(){rules(document.body)};root.querySelectorAll('[data-crumb]').forEach(function(b){b.onclick=function(){var min=ROOT.length;var next=Number(b.dataset.crumb)+1;if(next<min)return;webState.org=webState.org.slice(0,next);webState.page=1;renderWeb()}});root.querySelectorAll('[data-drill]').forEach(function(b){b.onclick=function(){webState.org.push(b.dataset.drill);webState.page=1;renderWeb()}});bindWebList(root)}
  function webSummary(){var names=children(webState.org),list=webRecords();function stat(sub){var rs=list.filter(function(r){return r.student.org[webState.org.length]===sub});return '<td>'+new Set(rs.map(function(r){return r.studentId})).size+'</td><td>'+rs.length+'</td>'}return '<table class="c3-summary"><thead><tr><th>'+['省份名称','地市名称','区县名称','学校名称'][webState.org.length]+'</th><th>关爱学生数</th><th>关爱次数</th></tr></thead><tbody>'+names.map(function(n){return '<tr><td><button data-drill="'+esc(n)+'">'+esc(n)+'</button></td>'+stat(n)+'</tr>'}).join('')+'<tr><th>合计</th><th>'+new Set(list.map(function(r){return r.studentId})).size+'</th><th>'+list.length+'</th></tr></tbody></table>'}
  function webList(){var list=webRecords(),f=webState.filter,total=Math.max(1,Math.ceil(list.length/10)),rows=list.slice((webState.page-1)*10,webState.page*10);return '<form class="c3-filters" id="care3-filters"><label>学年<select name="year">'+options(Array.from(new Set(list.map(function(r){return yearOf(r.careDate)}))),f.year,'全部学年')+'</select></label><label>年级<select name="grade">'+options(Array.from(new Set(list.map(function(r){return r.student.grade}))),f.grade,'全部年级')+'</select></label><label>班级<select name="className">'+options(Array.from(new Set(list.map(function(r){return r.student.className}))),f.className,'全部班级')+'</select></label><label style="position:relative">学生姓名<input name="name" type="search" list="care3-web-names" placeholder="请输入学生姓名" value="'+esc(f.name)+'"><datalist id="care3-web-names">'+Array.from(new Set(list.map(function(r){return r.student.name}))).map(function(n){return '<option value="'+esc(n)+'"></option>'}).join('')+'</datalist></label><label>关爱来源<select name="source">'+options(SOURCES,f.source,'全部')+'</select></label><label>创建日期<input name="start" value="'+esc(f.start)+'" placeholder="YYYY-MM-DD">—<input name="end" value="'+esc(f.end)+'" placeholder="YYYY-MM-DD"></label><button class="c3-primary">查询</button><button class="c3-plain" type="button" data-reset>重置</button><span class="c3-error" data-query-error></span></form><div class="c3-count">共 '+list.length+' 条关爱记录</div><div class="c3-table-scroll"><table><colgroup><col style="width:95px"><col style="width:145px"><col style="width:75px"><col style="width:145px"><col style="width:138px"><col style="width:140px"><col style="width:175px"><col style="width:100px"><col style="width:215px"><col style="width:90px"></colgroup><thead><tr><th>学生姓名</th><th>年级</th><th>班级</th><th>创建时间</th><th>关爱来源</th><th>关爱类型</th><th>关爱原因</th><th>关爱时间</th><th>关爱结果</th><th class="c3-operation">操作</th></tr></thead><tbody>'+(rows.length?rows.map(function(r){return '<tr><td>'+esc(r.student.name)+'</td><td>'+esc(r.student.grade)+'</td><td>'+esc(r.student.className)+'</td><td>'+esc(r.createdAt.slice(0,16))+'</td><td title="'+esc(r.sources.join('、'))+'">'+esc(short(r.sources.join('、')))+'</td><td title="'+esc(r.types.join('、'))+'">'+esc(short(r.types.join('、')))+'</td><td title="'+esc(r.reason)+'">'+esc(r.reason)+'</td><td>'+esc(r.careDate)+'</td><td title="'+esc(r.result)+'">'+esc(r.result)+'</td><td class="c3-operation"><button class="c3-link" data-web-detail="'+r.id+'">详情</button></td></tr>'}).join(''):'<tr><td colspan="10" class="c3-empty">暂无符合条件的关爱记录</td></tr>')+'</tbody></table></div><div class="c3-pager"><span>共 '+list.length+' 条，每页10条</span><span><button class="c3-plain" data-prev '+(webState.page===1?'disabled':'')+'>上一页</button> '+webState.page+' / '+total+' <button class="c3-plain" data-next '+(webState.page===total?'disabled':'')+'>下一页</button></span></div>'}
  function bindWebList(root){var form=root.querySelector('#care3-filters');if(!form)return;form.onsubmit=function(e){e.preventDefault();var next=Object.fromEntries(new FormData(form));var err=form.querySelector('[data-query-error]');if((next.start&&!validDate(next.start))||(next.end&&!validDate(next.end))||(next.start&&next.end&&next.start>next.end)){err.textContent='开始日期不能晚于结束日期，请检查日期范围';return}webState.filter=next;webState.page=1;renderWeb()};form.querySelector('[data-reset]').onclick=function(){webState.filter={year:'',grade:'',className:'',name:'',source:'',start:today(),end:today()};webState.page=1;renderWeb()};root.querySelector('[data-prev]')?.addEventListener('click',function(){webState.page--;renderWeb()});root.querySelector('[data-next]')?.addEventListener('click',function(){webState.page++;renderWeb()});root.querySelectorAll('[data-web-detail]').forEach(function(b){b.onclick=function(){openWebDetail(b.dataset.webDetail)}})}
  function openWebDetail(id){var r=records.find(function(x){return x.id===id});if(!r)return;var m=modal(document.body,'<div class="c3-dialog-head"><b>关爱记录详情</b><button data-close>×</button></div><div class="c3-dialog-body"><div class="c3-card">'+studentHead(r.student)+'</div><div class="c3-card"><b>关爱内容</b>'+kv('关爱来源',r.sources.join('、'))+kv('关爱类型',r.types.join('、'))+kv('关爱原因',r.reason)+kv('关爱时间',r.careDate)+kv('执行人员',r.people.join('、'))+kv('关爱方式',r.method)+kv('关爱结果',r.result)+kv('证明材料',r.proofs.length?r.proofs.length+'张':'--')+kv('创建人',r.createdName)+kv('创建时间',r.createdAt.slice(0,16))+'</div></div><div class="c3-dialog-foot"><button class="c3-primary" data-close>关闭</button></div>');m.querySelectorAll('[data-close]').forEach(function(b){b.onclick=function(){m.remove()}})}
  if(isTeacher)installTeacher();else installWeb();
